const fullText = items[0].json.text;
const chunkSize = 4000; 
const overlap = 400; 
const chunks = [];

// 1. Zuerst alle Chunks erstellen
for (let i = 0; i < fullText.length; i += (chunkSize - overlap)) {
    chunks.push({
        json: {
            chunkContent: fullText.substring(i, i + chunkSize),
            chunkIndex: chunks.length + 1
        }
    });
}

// 2. Die Gesamtzahl ermitteln
const totalChunks = chunks.length;

// 3. Jedem Chunk die totalChunks hinzufügen
chunks.forEach(item => {
    item.json.totalChunks = totalChunks;
});

return chunks;

// 1. Zuerst das ".pdf" am Ende entfernen (Groß-/Kleinschreibung ignoriert)
// 2. Dann alle Sonderzeichen durch Unterstriche ersetzen
const cleanName = $input.item.json.name
  .replace(/\.pdf$/i, '') 
  .replace(/[^a-zA-Z0-9]/g, '_');

return {
  normalizedName: cleanName
};

let raw = $json.text ?? '';

if (typeof raw !== 'string') {
  raw = JSON.stringify(raw);
}

let text = raw
  .replace(/```json/gi, '')
  .replace(/```/g, '')
  .replace(/\*\*/g, '')
  .replace(/\r/g, '')
  .trim();

// Normalize labels
text = text
  .replace(/script\s*1\s*:?/gi, 'VERSION 1:')
  .replace(/script\s*2\s*:?/gi, 'VERSION 2:')
  .replace(/script\s*3\s*:?/gi, 'VERSION 3:')
  .replace(/version\s*1\s*:?/gi, 'VERSION 1:')
  .replace(/version\s*2\s*:?/gi, 'VERSION 2:')
  .replace(/version\s*3\s*:?/gi, 'VERSION 3:');

// Remove separators
text = text.replace(/\n\s*-{3,}\s*\n/g, '\n');

const match = text.match(
  /VERSION 1:\s*([\s\S]*?)\s*VERSION 2:\s*([\s\S]*?)\s*VERSION 3:\s*([\s\S]*)/i
);

if (!match) {
  throw new Error('Could not find VERSION 1, VERSION 2, and VERSION 3 in this item.');
}

const cleanScript = (value) => {
  return value
    .replace(/^[-–—\s]+/g, '')
    .replace(/\n+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
};

const script_1 = cleanScript(match[1]);
const script_2 = cleanScript(match[2]);
const script_3 = cleanScript(match[3]);

if (!script_1 || !script_2 || !script_3) {
  throw new Error('One or more scripts are empty.');
}

// Correct return format for "Run Once for Each Item"
return {
  json: {
    output: {
      script_1,
      script_2,
      script_3,
    },
  },
};
